import { Keyboard, TextInput, View } from 'react-native';
import React, { useEffect } from 'react';

export default function App() {
  useEffect(() => {
    const showSub = Keyboard.addListener('keyboardDidShow', () => console.log('Keyboard shown'));
    const hideSub = Keyboard.addListener('keyboardDidHide', () => console.log('Keyboard hidden'));

    return () => {
      showSub.remove();
      hideSub.remove();
    };
  }, []);

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <TextInput placeholder='Type here...' style={{ borderWidth: 1, width: 200, padding: 10 }} />
    </View>
  );
}
